export function hydrateFathomMockPack(idea: ContentIdea): ContentIdea {
  const template = FATHOM_CONTENT_PACKS[idea.id];
  return template && idea.isMock && !idea.mockContentPack ? { ...idea, mockContentPack: template } : idea;
}
